<?php
namespace Modules\Suppliers\Http\Controllers;
use Modules\Suppliers\Http\Controllers\SuppliersBaseController as Controller; use Illuminate\Http\Request; use Modules\Suppliers\Entities\Supplier;
class SupplierContactTabController extends Controller { public function index(Supplier $supplier){ $this->check($supplier); return view('suppliers::contacts.index', compact('supplier')); } public function store(Request $request, Supplier $supplier){ $this->check($supplier); return back()->with('status', __('suppliers::lang.contact_saved_successfully')); } public function update(Request $request, Supplier $supplier, $contact){ $this->check($supplier); return back()->with('status', __('suppliers::lang.contact_updated_successfully')); } public function destroy(Supplier $supplier, $contact){ $this->check($supplier); return back()->with('status', __('suppliers::lang.contact_deleted_successfully')); } private function check(Supplier $supplier): void { abort_unless((int)$supplier->business_id === (int)\Modules\Suppliers\Utils\SupplierContextUtil::businessId() && $supplier->type === 'supplier', 404); } }
